		place-items: center;
		border-radius: 9999px;
		background: var(--color-brand-sand-soft);
		color: var(--color-brand-red);
	}
	.toast-icon svg {
		height: 1rem;
		width: 1rem;
	}

	.toast-body {
		display: flex;
		min-width: 0;
		flex-direction: column;
		text-align: left;
	}
	.toast-top {
		font-size: 0.65rem;
		font-weight: 600;
		text-transform: uppercase;
		letter-spacing: 0.02em;
		color: var(--color-brand-charcoal-soft);
	}
	.toast-name {
		overflow: hidden;
		font-size: 0.8rem;
		font-weight: 700;
		line-height: 1.2;
		color: var(--color-brand-charcoal);
		display: -webkit-box;
		-webkit-box-orient: vertical;
		-webkit-line-clamp: 2;
		line-clamp: 2;
	}
	.toast-price {
		margin-top: 0.1rem;
		font-size: 0.8rem;
		font-weight: 600;
		color: var(--color-brand-red);
	}
</style>
